import{_ as o,l,o as e,c as n,v as r,p as s,x as t,d as h,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"CO₂ 驱动激光放大链","description":"","frontmatter":{"title":"CO₂ 驱动激光放大链","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/co2-drive-laser-chain.md","filePath":"litho/co2-drive-laser-chain.md","lastUpdated":1789023840000}'),d={name:"litho/co2-drive-laser-chain.md"};function c(m,a,A,P,C,_){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="co2-驱动激光放大链" tabindex="-1">CO₂ 驱动激光放大链 <a class="header-anchor" href="#co2-驱动激光放大链" aria-label="Permalink to &quot;CO₂ 驱动激光放大链&quot;">​</a></h1><div class="epigraph"><p>落到硅片上的 13.5 nm 不是这台激光器的输出。十千瓦级 CO₂ 放大链只负责把能量送到锡滴；EUV 是等离子体自己辐射出来的。</p><footer>—— 对照 ASML / Cymer 对 LPP 驱动激光的公开架构；Bakshi, EUV Lithography</footer></div><p><a href="/litho/scanner-calibration-cycle">上一课</a>把 DUV 扫描仪的剂量、焦点、网格和照明零点钉成校准周期。曝光机单元收到那里。缺口是：EUV 进阶的第一张合同不是再校一台 ArF，而是另一条光源——<a href="/litho/euv-lpp-tin">LPP</a> 的驱动激光本身是一条脉冲 CO₂ 主振–功放（MOPA）链。后课谈转换效率、锡谱和收集镜，都默认本课的 10.6 μm 放大链已经读完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>校准课把「灯」当成会漂的执行器。EUV 的灯不是放电腔里的 ArF*，而是真空里的锡等离子体；点燃它的是红外驱动光。公开叙述里，主脉冲来自 10.6 μm 的 CO₂，平均功率十千瓦量级，重复频率数十千赫，脉宽纳秒级。单台振荡器给不出这个组合：要窄脉冲、要能量、还要在 50 kHz 量级上打几十亿次而不把增益介质打穿。</p><p>缺口因此是放大链，不是再讲一遍锡滴几何。种子从哪来、经过几级放大、脉冲包络怎样被整形，决定主脉冲能不能打在<a href="/litho/euv-prepulse">预脉冲</a>展开后的盘靶上。链不稳，剂量环会把噪声锁进每场；链饱和，IF 功率广告值永远到不了硅片。</p><p><span class="marginnote">驱动光是 10.6 μm，曝光光是 13.5 nm。投影物镜里没有 CO₂。把「EUV 激光器」画成一台直接出 13.5 nm 的腔，是把本课和 LPP 课一起读错了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开架构是 MOPA：主振荡器出种子，功率放大级把能量抬到打靶所需。振荡级管时序、重频和包络形状；放大级管能量。工业 CO₂ 常用射频激励的气体放电，多程通过增益介质提取。预脉冲若用另一路固体激光或另一段 CO₂，瞄准与延时和主链锁在同一滴探测伺服上，能量账却分开记——预脉冲几乎不贡献带内 EUV。</p><p>计量在两处：激光侧看种子能量、放大后 \\(E_p\\)、指向与脉宽；源侧看滴命中率和 <a href="/litho/intermediate-focus">IF</a> 带内功率。剂量环的执行器包括放电/射频功率和触发延时，不是物镜里的滤光片。刚开机、换气或改重频后的瞬态要丢弃，与 ArF <a href="/litho/source-power-stability">换气丢脉冲</a> 同构，介质换成 CO₂。</p><h3 id="链与滴必须锁在同一时钟" tabindex="-1">链与滴必须锁在同一时钟 <a class="header-anchor" href="#链与滴必须锁在同一时钟" aria-label="Permalink to &quot;链与滴必须锁在同一时钟&quot;">​</a></h3><p>50 kHz 量级意味着每 20 μs 一次完整击打。种子触发由滴探测给出，放大链的存储能量和热透镜却有更长的时间常数。链可以平均功率合格，单次脉冲仍打在盘靶边缘。后课 CE 默认：不合格的命中率先修链的指向与延时，再谈等离子体分支。</p>',12)),(e(),s(p,null,{default:t(()=>[E(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22CO2%20%E4%B8%BB%E6%8C%AF%E8%8D%A1%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20AMP%5B%22%E5%A4%9A%E7%A8%8B%E5%8A%9F%E7%8E%87%E6%94%BE%E5%A4%A7%22%5D%0A%20%20AMP%20--%3E%20MP%5B%22%E4%B8%BB%E8%84%89%E5%86%B2%2010.6%20%CE%BCm%22%5D%0A%20%20PP%5B%22%E9%A2%84%E8%84%89%E5%86%B2%22%5D%20--%3E%20TGT%5B%22%E5%B1%95%E5%BC%80%E5%90%8E%E7%9A%84%E9%94%A1%E9%9D%B6%22%5D%0A%20%20MP%20--%3E%20TGT%0A%20%20TGT%20--%3E%20EUV%5B%22%E9%94%A1%E7%AD%89%E7%A6%BB%E5%AD%90%E4%BD%93%2013.5%20nm%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CO₂ 的 00⁰1–10⁰0 带在 10.6 μm。这个波长把等离子体临界密度放在相对稀薄的冕区，有利于带内吸收，细节留给下一课的转换效率。放大链要解决的是提取：准分子式「短寿命、单次放电」在这里换成可重复的气体增益。饱和通量、多程几何和热透镜决定你能从每级抽出多少，而不把光束质量毁掉——指向一歪，主脉冲打在盘靶边缘，CE 和碎屑谱一起变。</p><p>重复频率把单脉冲能量与平均功率拆开。单脉冲过高，流体力学把靶打成喷溅；频率过低，扫描狭缝攒不够光子。链的热管理、气体循环和光学损伤阈值，限制的是可维持的平均红外功率，不是示波器上的峰值。Fomenkov 等在 SPIE 先进光刻会议上给出的量产叙事，始终是「可维持的驱动 + 可维持的 IF」，而不是实验室单脉冲。</p><p><span class="marginnote">Bakshi 书里的驱动激光章节解释为什么选 CO₂；ASML/Cymer 公开的是 MOPA 与锡滴集成。不要把会议海报上的放大器级数写成厂内配置表。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 CE、UTA 和收集镜寿命写完。下一课只问：打到靶上的红外，有多少变成 2% 带内 EUV。也不重写 ArF 准分子放电——气体、波长、靶都不一样。Gigaphoton 等另一条 LPP 链同样用 CO₂ 打锡，架构细节以各自公开材料为准，机制同属本课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV 量产驱动光是脉冲 CO₂ 放大链，不是 13.5 nm 激光腔。</li><li>MOPA 把时序与能量分开；指向和包络决定打靶质量。</li><li>后课默认：说到「加功率」，先问链是否还在线性提取区。</li><li>出处：ASML/Cymer LPP 驱动激光公开架构；Bakshi, <em>EUV Lithography</em>；Fomenkov 等 SPIE 光源论文。</li></ul>',8))])}const f=o(d,[["render",c]]);export{B as __pageData,f as default};
